let dplf = find_bytes("44 50 4C 46");
for addr in dplf {
  report("DexProtector Payload (DPLF)", addr, "HIGH", "Embedded DPLF packed-library magic");
}
let str_sigs = [
  ["libshell", "Tencent Legu Indicator", "HIGH", "Tencent Legu packer stub reference"],
  ["libsecexe", "Bangcle / SecNeo Indicator", "HIGH", "Bangcle packer library reference"],
  ["libDexHelper", "Alibaba DexHelper Indicator", "HIGH", "Alibaba DexHelper packer library reference"],
  ["libmobisec", "Alibaba MobiSec Indicator", "HIGH", "Alibaba MobiSec protector library reference"],
  ["libnesec", "NetEase Sec Indicator", "HIGH", "NetEase (libnesec) protector library reference"],
  ["libbaiduprotect", "Baidu Protect Indicator", "HIGH", "Baidu protect packer library reference"],
  ["DexClassLoader", "ART DexClassLoader", "MEDIUM", "Dynamic DEX loading / unpacking indicator"]
];
let pairip_vm = find_symbols("ExecuteProgram");
for s in pairip_vm {
  if s.name == "ExecuteProgram" && s.address > 0 {
    report("PairIP VM Entrypoint (ExecuteProgram)", s.address, "HIGH", "PairIP bytecode VM interpreter called by VMRunner");
  }
}
for sig in str_sigs {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
}
let jni = find_symbols("JNI_OnLoad");
for s in jni {
  let insns = disasm(s.address, 64);
  let n = insns.len();
  let found = false;
  let i = 0;
  while i < n && !found {
    let m = insns[i].mnemonic;
    if m == "adr" || m == "adrp" {
      let reg = insns[i].op_str.split(",")[0].trim();
      let j = i + 1;
      while j < n && j <= i + 24 {
        if insns[j].mnemonic == "br" && insns[j].op_str.trim() == reg {
          report("DexProtector Obfuscated JNI_OnLoad", s.address, "HIGH", "Indirect branch trampoline (" + insns[i].op_str + " -> br " + reg + ")");
          found = true;
          break;
        }
        j += 1;
      }
    }
    i += 1;
  }
}
let is_dexprotector = dplf.len() > 0;
let sys_syms = find_symbols("syscall");
if is_dexprotector && sys_syms.len() > 0 {
  for s in sys_syms {
    if s.name == "syscall" && s.address > 0 {
      report("DexProtector / RASP Syscall Import", s.address, "HIGH", "Direct syscall from a DPLF-packed binary (anti-tamper profile)");
      let xrefs = get_xrefs(s.address);
      for x in xrefs {
        report("Direct syscall() Call Site", x.from, "HIGH", x.instruction);
      }
    }
  }
}
